<style>.iam{display:grid;gap:18px;color:#ece8dc}.iam-hero,.iam-panel,.iam-card{border:1px solid #4b4022;background:linear-gradient(145deg,#111,#191712);border-radius:18px;padding:22px}.iam-hero{display:flex;justify-content:space-between;gap:16px;align-items:end}.iam h1{font-size:clamp(1.7rem,4vw,3rem);margin:5px 0}.iam-kicker,.iam th{color:#d7ad45;text-transform:uppercase;letter-spacing:.12em;font-size:.72rem}.iam-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.iam-card strong{display:block;font-size:1.8rem;color:#e8c76b}.iam-nav,.iam-actions{display:flex;flex-wrap:wrap;gap:8px}.iam-btn{display:inline-flex;padding:9px 13px;border-radius:10px;border:1px solid #9b7a2c;background:#d7ad45;color:#15120a;font-weight:700;text-decoration:none}.iam-btn.alt{background:transparent;color:#e8c76b}.iam-table{overflow-x:auto}.iam table{width:100%;min-width:720px;border-collapse:collapse}.iam td,.iam th{padding:12px;border-bottom:1px solid #332d1e;text-align:left}.iam input,.iam select,.iam textarea{width:100%;padding:10px;border:1px solid #554620;border-radius:9px;background:#0d0d0d;color:#fff}.iam form{display:grid;gap:10px}.iam-status{border:1px solid #806927;border-radius:999px;padding:4px 9px;color:#e8c76b;font-size:.75rem}@media(max-width:700px){.iam-grid{grid-template-columns:1fr 1fr}.iam-hero{align-items:start;flex-direction:column}.iam-panel,.iam-card,.iam-hero{padding:16px}.iam{min-width:0}.iam-table{max-width:100%}}</style>
